qasm_string = """OPENQASM 3.0;
include "stdgates.inc";

gate oracle q0, q1, q2, q3, q4, q5, q6, q7, q8, q9, q10, q11, q12, q13, q14, q15 {
  // Select s1 = 00010111 with p=0.5, else s2 = 10101111
  // Random selector qubit: q15
  h q15;

  // Compute c(x) for s1 using j=3: if x3==1 then x ^= s1 (bits 4,6,7)
  cx q3, q4;
  cx q3, q6;
  cx q3, q7;

  // Compute c(x) for s2 using j=0: if x0==1 then x ^= s2 (bits 0,2,4,5,6,7)
  // Controlled on selector being 1 (q15) as well: apply when q15=1 AND x0=1
  ccx q15, q0, q0;
  ccx q15, q0, q2;
  ccx q15, q0, q4;
  ccx q15, q0, q5;
  ccx q15, q0, q6;
  ccx q15, q0, q7;

  // Uncompute the extra flip on x0 caused by the s2 step (since s2 has bit0=1)
  ccx q15, q0, q0;

  // Copy c into output: y ^= c
  cx q0, q8;
  cx q1, q9;
  cx q2, q10;
  cx q3, q11;
  cx q4, q12;
  cx q5, q13;
  cx q6, q14;
  cx q7, q15;

  // XOR key b = 01101111 into output (qubits 8..15)
  // b bits: [0..7] = 0 1 1 0 1 1 1 1
  x q9;
  x q10;
  x q12;
  x q13;
  x q14;
  x q15;
}

qubit[16] q;
oracle q[0], q[1], q[2], q[3], q[4], q[5], q[6], q[7], q[8], q[9], q[10], q[11], q[12], q[13], q[14], q[15];
"""
END_FILE>>>

